import{_ as o}from"./chunks/02.P88t_cDR.js";import{_ as n,o as r,c as d,j as t,a as e,aa as s}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/academy/img/prava-v-denicich/02.webp",y=JSON.parse('{"title":"Kdo co smí v deníku","description":"","frontmatter":{"title":"Kdo co smí v deníku","wiki":"cs:diary:userpermissions"},"headers":[],"relativePath":"diary/userpermissions.md","filePath":"diary/userpermissions.md","lastUpdated":1794209661000}'),v={name:"diary/userpermissions.md"};function m(p,a,l,u,k,c){return r(),d("div",null,[...a[0]||(a[0]=[t("h1",{id:"kdo-co-smi-v-deniku",tabindex:"-1"},[e("Kdo co smí v deníku "),t("a",{class:"header-anchor",href:"#kdo-co-smi-v-deniku","aria-label":'Permalink to "Kdo co smí v deníku"'},"​")],-1),t("p",null,"Co uživatel v Buildary smí, se určuje na třech úrovních: v doméně, na stavbě a v deníku. Pro práci v deníku je rozhodující role oprávněné osoby – z ní plynou kompetence, tedy co smí v deníku zapisovat a nastavovat.",-1),t("p",null,[e("Krok za krokem: "),t("a",{href:"/buildary-help-preview/akademie/prava-v-denicich"},"Zjistit, kdo má jaká práva v denících"),e(" v Akademii.")],-1),t("div",{class:"video"},[t("iframe",{src:"https://www.youtube-nocookie.com/embed/akZLFxBlluo",title:"Video: Uživatelská práva",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),s('<h2 id="tri-urovne-prav" tabindex="-1">Tři úrovně práv <a class="header-anchor" href="#tri-urovne-prav" aria-label="Permalink to &quot;Tři úrovně práv&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Úroveň</th><th>Kde se nastavuje</th><th>Co určuje</th></tr></thead><tbody><tr><td><strong>Doména</strong></td><td>Detail domény → <strong>Uživatelé domény</strong></td><td>Kdo smí spravovat doménu, zakládat stavby a spravovat stavby firmy.</td></tr><tr><td><strong>Stavba</strong></td><td>Nastavení stavby → <strong>Projektový tým</strong></td><td>Kdo má na stavbu přístup a jaké kompetence mají jednotlivé role.</td></tr><tr><td><strong>Deník</strong></td><td>Identifikační údaje → <strong>Oprávněné osoby</strong></td><td>Kdo má přístup do deníku a v jaké roli.</td></tr></tbody></table><p>Na malé stavbě v osobní doméně se o práva starat nemusíte – máte v ní vždy všechna práva. Úrovně stavby a deníku ale musí pochopit každý, kdo deník spravuje.</p><h2 id="domena" tabindex="-1">Doména <a class="header-anchor" href="#domena" aria-label="Permalink to &quot;Doména&quot;">​</a></h2><p>Práva v doméně nastavuje administrátor firemní domény. Uživatelé, kteří pracují jen na stavbách, kam je někdo pozval, nebo jen ve své osobní doméně, je řešit nemusí.</p><table tabindex="0"><thead><tr><th>Právo</th><th>Co uživateli umožní</th></tr></thead><tbody><tr><td><strong>Administrace domény</strong></td><td>Upravovat údaje domény, přidávat uživatele domény a nastavovat jim práva, smazat doménu, zakládat vzorové stavby. Vidí všechny stavby domény, ale nemůže je upravovat.</td></tr><tr><td><strong>Založení stavby</strong></td><td>Zakládat stavby v doméně.</td></tr><tr><td><strong>Správa stavby</strong></td><td>Na stavbách, kde je členem projektového týmu, upravovat údaje stavby, přidávat firmy a členy týmu a zakládat deníky.</td></tr><tr><td><strong>Administrace všech staveb</strong></td><td>Nastavovat všechny stavby domény bez ohledu na to, kdo je založil: firmy, členy týmu, role, deníky, úvodní listy a oprávněné osoby. V denních záznamech má jen právo čtení – nesmí zapisovat ani doplňovat dokumenty.</td></tr><tr><td><strong>Čtenář všech staveb</strong></td><td>Prohlížet všechny deníky v doméně, bez možnosti cokoli měnit.</td></tr></tbody></table><p>Kdo doménu založil, je jejím vlastníkem a má vždy práva administrátora domény – odebráním ani změnou práv ho omezit nejde. Jak doménu založit a přidat do ní uživatele, popisuje <a href="/buildary-help-preview/firstofall/domain#spravovat-domenu">Firemní doména</a>.</p><h2 id="stavba" tabindex="-1">Stavba <a class="header-anchor" href="#stavba" aria-label="Permalink to &quot;Stavba&quot;">​</a></h2><p>Přístup na stavbu má každý <strong>člen projektového týmu</strong>. Po přidání do týmu mu přijde pozvánka e-mailem. Samotné členství ale ještě nedává právo pracovat v deníku – do deníku musí být člen přidán jako oprávněná osoba.</p><p>Každý člen má v týmu <strong>výchozí roli</strong>. Ta se mu předvyplní, když ho přidáte do deníku, a určuje i jeho kompetence na stavbě. Pokud je člen ze stejné domény jako stavba, platí mu na stavbě navíc práva z domény. Jak členy a firmy přidat, popisuje <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>.</p><h3 id="kompetence-roli" tabindex="-1">Kompetence rolí <a class="header-anchor" href="#kompetence-roli" aria-label="Permalink to &quot;Kompetence rolí&quot;">​</a></h3><p>Které kompetence má která role, vidíte a upravujete v Projektovém týmu na záložce <strong>Role členů</strong>. Můžete si vytvořit i vlastní role.</p><figure class="shot" style="--w:760px;"><img src="'+o+'" alt="Záložka Role členů s tabulkou kompetencí jednotlivých rolí" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Kompetence</th><th>Co role smí</th></tr></thead><tbody><tr><td><strong>Administrace stavby</strong></td><td>Rozšiřovat projektový tým a upravovat Nastavení stavby včetně číselníků.</td></tr><tr><td><strong>Administrace deníku</strong></td><td>Upravovat identifikační údaje deníku, přidávat oprávněné osoby, měnit <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a> a smazat deník (jen dokud nemá podepsané a uzamčené dny).</td></tr><tr><td><strong>Pravidelné záznamy</strong></td><td>Zapisovat do sekcí Počasí, Osoby na staveništi, Mechanizmy, Materiály a Provedené práce.</td></tr><tr><td><strong>Další záznamy</strong></td><td>Zapisovat do sekce Další záznamy.</td></tr><tr><td><strong>Dokumenty stavby</strong></td><td>Zapisovat do Dokumentů deníku: základní doklady, projektová dokumentace, kontroly a zkoušky, ostatní dokumenty.</td></tr><tr><td><strong>Části stavby a výkresy</strong></td><td>Spravovat části stavby a výkresy, viz <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>.</td></tr><tr><td><strong>Správa projektového týmu</strong></td><td>Přidávat členy a firmy na stavbu a přidávat oprávněné osoby do deníku.</td></tr><tr><td><strong>Nový stavební deník kopií</strong></td><td>Založit nový deník kopií existujícího.</td></tr><tr><td><strong>Ukončení stavby</strong></td><td>Ukončit stavbu, viz <a href="/buildary-help-preview/diary/projectended">Ukončit stavbu</a>.</td></tr></tbody></table><p>Záznamy může každý upravovat a mazat jen své vlastní, a to jen do uzamčení dne nebo záznamu.</p><p>Kompetence pro soupisy provedených prací popisuje <a href="/buildary-help-preview/performedworks/competences">Kompetence pro soupisy</a>.</p><h2 id="denik" tabindex="-1">Deník <a class="header-anchor" href="#denik" aria-label="Permalink to &quot;Deník&quot;">​</a></h2><p>Do deníku má přístup jen ten, kdo je v něm <strong>oprávněnou osobou</strong>. Oprávněné osoby přidáváte v identifikačních údajích deníku, viz <a href="/buildary-help-preview/diary/diaryidentification#opravnene-osoby">Oprávněné osoby</a>.</p><ul><li>Role se předvyplní z projektového týmu, v každém deníku ji ale můžete změnit. Tentýž člověk tak může být v jednom deníku stavbyvedoucí a v jiném jen čtenář.</li><li>Každá oprávněná osoba smí prohlížet celý deník, ať má jakoukoli roli – to vyplývá ze zákona.</li><li>Kdo deník založil, je jeho vlastníkem a má v něm vždy práva administrátora deníku.</li><li>Pokud má stavba nastavenou volbu <strong>Stavba s jedním deníkem</strong>, každý nový člen projektového týmu se do deníku přidá jako oprávněná osoba automaticky.</li></ul><h3 id="prehled-prav-v-denicich" tabindex="-1">Přehled práv v denících <a class="header-anchor" href="#prehled-prav-v-denicich" aria-label="Permalink to &quot;Přehled práv v denících&quot;">​</a></h3><p>Kdo má v kterém deníku jakou roli, vidíte na jednom místě v Projektovém týmu na záložce <strong>Práva v denících</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Záložka Práva v denících s uživateli, deníky a jejich rolemi" loading="lazy"></figure><h2 id="co-k-cemu-potrebujete" tabindex="-1">Co k čemu potřebujete <a class="header-anchor" href="#co-k-cemu-potrebujete" aria-label="Permalink to &quot;Co k čemu potřebujete&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chcete</th><th>Potřebujete</th></tr></thead><tbody><tr><td>Založit stavbu ve firemní doméně</td><td>Právo <strong>Založení stavby</strong> v doméně.</td></tr><tr><td>Založit deník</td><td>Právo <strong>Správa stavby</strong> nebo <strong>Administrace všech staveb</strong> v doméně. Deník kopií také kompetenci <strong>Nový stavební deník kopií</strong>.</td></tr><tr><td>Přidat člověka na stavbu</td><td>Kompetenci <strong>Administrace stavby</strong> nebo <strong>Správa projektového týmu</strong>.</td></tr><tr><td>Přidat oprávněnou osobu do deníku</td><td>Kompetenci <strong>Administrace deníku</strong> nebo <strong>Správa projektového týmu</strong>.</td></tr><tr><td>Změnit Nastavení deníku</td><td>Kompetenci <strong>Administrace deníku</strong>.</td></tr><tr><td>Zapisovat denní záznamy</td><td>Být oprávněnou osobou s kompetencí <strong>Pravidelné záznamy</strong>.</td></tr><tr><td>Zapisovat Další záznamy</td><td>Být oprávněnou osobou s kompetencí <strong>Další záznamy</strong>.</td></tr><tr><td>Deník jen číst</td><td>Být oprávněnou osobou s jakoukoli rolí, například <strong>Čtenář deníku</strong>.</td></tr></tbody></table><p>V osobní doméně máte na svých stavbách všechna práva automaticky.</p>',25)])])}const g=n(v,[["render",m]]);export{y as __pageData,g as default};
